import{_ as n}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as d}from"./chunks/fw_runway_takeoff_wheel_steering.CRHIXYjJ.js";import{_ as l,C as h,o as _,c as s,al as i,j as t,a,E as o}from"./chunks/framework.7vp1BMOE.js";const b=JSON.parse('{"title":"Takeoff Mode (Fixed-Wing)","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_modes_fw/takeoff.md","filePath":"en/flight_modes_fw/takeoff.md"}'),c={name:"en/flight_modes_fw/takeoff.md"},f={class:"info custom-block"};function u(m,e,p,g,W,T){const r=h("Badge");return _(),s("div",null,[e[6]||(e[6]=i('<h1 id="takeoff-mode-fixed-wing" tabindex="-1">Takeoff Mode (Fixed-Wing) <a class="header-anchor" href="#takeoff-mode-fixed-wing" aria-label="Permalink to &quot;Takeoff Mode (Fixed-Wing)&quot;">​</a></h1><img src="'+n+'" title="Position fix required (e.g. GPS)" width="30px"><p>The <em>Takeoff</em> flight mode causes the vehicle to take off to a specified height and then enter <a href="./../flight_modes_fw/takeoff">Hold mode</a>.</p><p>Vehicles are <a href="#catapult-hand-launch">hand or catapult launched</a> by default, but can also be <a href="#RWTO_TKOFF">configured</a> to use a <a href="#runway-takeoff">runway takeoff</a> when supported by the hardware.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Mode is automatic - no user intervention is <em>required</em> to control the vehicle.</li><li>Mode requires at least a valid altitude estimation. <ul><li>Flying vehicles can&#39;t switch to this mode without valid altitude.</li><li>Flying vehicles will failsafe if they lose the altitude estimate.</li><li>Disarmed vehicles can switch to mode without valid altitude estimate but can&#39;t arm.</li></ul></li><li>RC control switches can be used to change flight modes.</li><li>RC stick movement is ignored in catapult takeoff but can be used to nudge the vehicle in runway takeoff.</li><li>The <a href="./../config/safety#failure-detector">Failure Detector</a> will automatically stop the engines if there is a problem on takeoff.</li></ul></div><h2 id="technical-summary" tabindex="-1">Technical Summary <a class="header-anchor" href="#technical-summary" aria-label="Permalink to &quot;Technical Summary&quot;">​</a></h2><p>Takeoff mode (and <a href="./../flight_modes_fw/mission#mission-takeoff">fixed wing mission takeoff</a>) has two modalities: <a href="#catapult-hand-launch">catapult/hand-launch</a> or <a href="#runway-takeoff">runway takeoff</a> (hardware-dependent). The mode defaults to catapult/hand launch, but can be set to runway takeoff by setting <a href="#RWTO_TKOFF">RWTO_TKOFF</a> to 1.</p><p>To use <em>Takeoff mode</em> you first switch to the mode, and then arm the vehicle (or send the <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_TAKEOFF" target="_blank" rel="noreferrer">MAV_CMD_NAV_TAKEOFF</a> command which does both). The acceleration of hand/catapult launch triggers the motors to start. For runway launch, motors ramp up automatically once the vehicle has been armed.</p><p>Irrespective of the modality, a flight path (starting point and takeoff course) and clearance altitude are defined:</p><ul><li>The starting point is the vehicle position when the takeoff mode is first entered.</li><li>The course is set to the vehicle heading on arming by default. If a valid waypoint latitude/longitude is set the vehicle will instead track towards the waypoint.</li><li>The clearance altitude is set to <a href="#MIS_TAKEOFF_ALT">MIS_TAKEOFF_ALT</a> by default. If a valid waypoint altitude is set is set the vehicle will instead use it as the clearance altitude.</li></ul><p>By default, on takeoff the aircraft will follow the line defined by the starting point and course, climbing at the maximum climb rate (<a href="./../advanced_config/parameter_reference#FW_T_CLMB_MAX">FW_T_CLMB_MAX</a>) until reaching the clearance altitude. Reaching the clearance altitude causes the vehicle to enter <a href="./../flight_modes_fw/takeoff">Hold mode</a>.</p><p><a href="#FW_TKO_CLMB_T">FW_TKO_CLMB_T</a> ends the climbout after a fixed time instead. The vehicle holds at whatever altitude it has reached by then, or climbs to the clearance altitude if it is still below it. Use it where altitude is a poor measure of when the climbout is done, such as a rocket-assisted launch.</p><p>If a valid waypoint target is set, using <code>MAV_CMD_NAV_TAKEOFF</code> or the <a href="./../msg_docs/VehicleCommand">VehicleCommand</a> uORB topic, the vehicle will instead track towards the waypoint, and enter <a href="./../flight_modes_fw/takeoff">Hold mode</a> after reaching the waypoint altitude (within the acceptance radius).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the local position is invalid or becomes invalid while executing the takeoff, the controller is not able to track a course setpoint and will instead proceed climbing while keeping the wings level until the clearance altitude is reached.</p></div>',14)),t("div",f,[e[5]||(e[5]=t("p",{class:"custom-block-title"},"INFO",-1)),t("ul",null,[t("li",null,[e[0]||(e[0]=a("Takeoff towards a target position was added in ",-1)),o(r,{type:"tip",text:"PX4 v1.17"}),e[1]||(e[1]=a(".",-1))]),t("li",null,[e[2]||(e[2]=a("Holding wings level and ascending to clearance attitude when local position is invalid during takeoff was added in ",-1)),o(r,{type:"tip",text:"PX4 v1.17"}),e[3]||(e[3]=a(".",-1))]),e[4]||(e[4]=t("li",null,[a("QGroundControl does not support "),t("code",null,"MAV_CMD_NAV_TAKEOFF"),a(" (at time of writing).")],-1))])]),e[7]||(e[7]=i('<h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li></ul><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h3><p>Parameters that affect both catapult/hand-launch and runway takeoffs:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="MIS_TAKEOFF_ALT"></a><a href="./../advanced_config/parameter_reference#MIS_TAKEOFF_ALT">MIS_TAKEOFF_ALT</a></td><td>This is the relative altitude (above launch altitude) the system will take off to if not otherwise specified. takeoff.</td></tr><tr><td><a id="FW_TKO_AIRSPD"></a><a href="./../advanced_config/parameter_reference#FW_TKO_AIRSPD">FW_TKO_AIRSPD</a></td><td>Takeoff airspeed (is set to <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a> if not defined by operator)</td></tr><tr><td><a id="FW_TKO_PITCH_MIN"></a><a href="./../advanced_config/parameter_reference#FW_TKO_PITCH_MIN">FW_TKO_PITCH_MIN</a></td><td>This is the minimum pitch angle setpoint during the climbout phase</td></tr><tr><td><a id="FW_T_CLMB_MAX"></a><a href="./../advanced_config/parameter_reference#FW_T_CLMB_MAX">FW_T_CLMB_MAX</a></td><td>Climb rate setpoint during climbout to takeoff altitude.</td></tr><tr><td><a id="FW_TKO_CLMB_T"></a><a href="./../advanced_config/parameter_reference#FW_TKO_CLMB_T">FW_TKO_CLMB_T</a></td><td>Duration of the climbout. If &gt; 0 the climbout ends after this time instead of at the takeoff altitude.</td></tr><tr><td><a id="FW_FLAPS_TO_SCL"></a><a href="./../advanced_config/parameter_reference#FW_FLAPS_TO_SCL">FW_FLAPS_TO_SCL</a></td><td>Flaps setpoint during takeoff</td></tr><tr><td><a id="FW_AIRSPD_FLP_SC"></a><a href="./../advanced_config/parameter_reference#FW_AIRSPD_FLP_SC">FW_AIRSPD_FLP_SC</a></td><td>Factor applied to the minimum airspeed when flaps are fully deployed. Needed if <a href="#FW_TKO_AIRSPD">FW_TKO_AIRSPD</a> is below <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a>.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The vehicle always respects normal FW max/min throttle settings during takeoff (<a href="./../advanced_config/parameter_reference#FW_THR_MIN">FW_THR_MIN</a>, <a href="./../advanced_config/parameter_reference#FW_THR_MAX">FW_THR_MAX</a>).</p></div><h2 id="hand_launch" tabindex="-1">Catapult/Hand Launch <a class="header-anchor" href="#hand_launch" aria-label="Permalink to &quot;Catapult/Hand Launch {#hand_launch}&quot;">​</a></h2><p>In <em>catapult/hand-launch mode</em> the vehicle waits to detect launch (based on acceleration trigger). On launch it enables the motor(s) and climbs with the maximum climb rate <a href="#FW_T_CLMB_MAX">FW_T_CLMB_MAX</a> while keeping the pitch setpoint above <a href="#FW_TKO_PITCH_MIN">FW_TKO_PITCH_MIN</a>. Once it reaches <a href="#MIS_TAKEOFF_ALT">MIS_TAKEOFF_ALT</a> it will automatically switch to <a href="./../flight_modes_fw/hold">Hold mode</a> and loiter. It is possible to delay the activation of the motors and control surfaces separately, see parameters <a href="#FW_LAUN_MOT_DEL">FW_LAUN_MOT_DEL</a>, <a href="#FW_LAUN_CS_LK_DY">FW_LAUN_CS_LK_DY</a> and <a href="#CA_CS_LAUN_LK">CA_CS_LAUN_LK</a>. The later is also exposed in the actuator configuration page under the advanced view.</p><p>All RC stick movement is ignored during the full takeoff sequence.</p><p>To launch in this mode:</p><ol><li>Arm the vehicle</li><li>Put the vehicle into <em>Takeoff mode</em></li><li>Launch/throw the vehicle (firmly) directly into the wind. You can also shake the vehicle first, wait till the motor spins up and then throw it</li></ol><h3 id="parameters-launch-detector" tabindex="-1">Parameters (Launch Detector) <a class="header-anchor" href="#parameters-launch-detector" aria-label="Permalink to &quot;Parameters (Launch Detector)&quot;">​</a></h3><p>The <em>launch detector</em> is affected by the following parameters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="FW_LAUN_DETCN_ON"></a><a href="./../advanced_config/parameter_reference#FW_LAUN_DETCN_ON">FW_LAUN_DETCN_ON</a></td><td>Enable automatic launch detection. If disabled motors spin up on arming already</td></tr><tr><td><a id="FW_LAUN_AC_THLD"></a><a href="./../advanced_config/parameter_reference#FW_LAUN_AC_THLD">FW_LAUN_AC_THLD</a></td><td>Acceleration threshold (norm of acceleration must be above this value)</td></tr><tr><td><a id="FW_LAUN_AC_T"></a><a href="./../advanced_config/parameter_reference#FW_LAUN_AC_T">FW_LAUN_AC_T</a></td><td>Trigger time (acceleration must be above threshold for this amount of seconds)</td></tr><tr><td><a id="FW_LAUN_MOT_DEL"></a><a href="./../advanced_config/parameter_reference#FW_LAUN_MOT_DEL">FW_LAUN_MOT_DEL</a></td><td>Delay from launch detection to motor spin up</td></tr><tr><td><a id="FW_LAUN_CS_LK_DY"></a><a href="./../advanced_config/parameter_reference#FW_LAUN_CS_LK_DY">FW_LAUN_CS_LK_DY</a></td><td>Delay from launch detection to unlocking the control surfaces</td></tr><tr><td><a id="CA_CS_LAUN_LK"></a><a href="./../advanced_config/parameter_reference#CA_CS_LAUN_LK">CA_CS_LAUN_LK</a></td><td>Bitmask to select which control surfaces are to be locked during launch</td></tr></tbody></table><h2 id="runway_launch" tabindex="-1">Runway Takeoff <a class="header-anchor" href="#runway_launch" aria-label="Permalink to &quot;Runway Takeoff {#runway_launch}&quot;">​</a></h2><p>Runway takeoffs can be used by vehicles with landing gear and steerable wheel (only). You will first need to enable the wheel controller using the parameter <a href="#FW_W_EN">FW_W_EN</a>.</p><p>Vehicle should be centered and aligned with runway when takeoff is initiated. The operator can &quot;nudge&quot; the vehicle while on the runway to help keeping it centered and aligned (see <a href="./../advanced_config/parameter_reference#RWTO_NUDGE">RWTO_NUDGE</a>).</p><p>The <em>runway takeoff mode</em> has the following phases:</p><ol><li><strong>Throttle ramp</strong>: Throttle is ramped up within <a href="./../advanced_config/parameter_reference#RWTO_RAMP_TIME">RWTO_RAMP_TIME</a> to <a href="./../advanced_config/parameter_reference#RWTO_MAX_THR">RWTO_MAX_THR</a>.</li><li><strong>Clamped to runway</strong>: Pitch fixed, no roll and takeoff path controlled until the rotation airspeed (<a href="./../advanced_config/parameter_reference#RWTO_ROT_AIRSPD">RWTO_ROT_AIRSPD</a>) is reached. The operator is able to nudge the vehicle left/right via yaw stick.</li><li><strong>Climbout</strong>: Increase pitch setpoint and climb to takeoff altitude. To prevent wingstrikes, the controller will keep the roll setpoint locked to 0 when close to the ground, and then gradually allow more roll while climbing. It is based on the vehicle geometry as configured in <a href="#FW_WING_SPAN">FW_WING_SPAN</a> and <a href="#FW_WING_HEIGHT">FW_WING_HEIGHT</a>.</li></ol><h3 id="wheel_controller" tabindex="-1">Wheel Controller <a class="header-anchor" href="#wheel_controller" aria-label="Permalink to &quot;Wheel Controller {#wheel_controller}&quot;">​</a></h3><p>The wheel controller steers the vehicle on the ground using the steerable nose/tail wheel. It is enabled with <a href="#FW_W_EN">FW_W_EN</a> and only runs in automatic modes during runway takeoff and during the landing rollout. Whenever it is not active (in all manual modes, or if it is disabled), the yaw stick is mapped directly to the wheel.</p><p>The controller is cascaded:</p><ol><li><strong>Heading controller</strong>: The heading (yaw) error is converted into a yaw rate setpoint with a fixed time constant of 0.1s, limited to <a href="#FW_W_RMAX">FW_W_RMAX</a>.</li><li><strong>Rate controller</strong>: A P-I-FF controller (<a href="#FW_WR_P">FW_WR_P</a>, <a href="#FW_WR_I">FW_WR_I</a>, <a href="#FW_WR_FF">FW_WR_FF</a>, integrator limited by <a href="#FW_WR_IMAX">FW_WR_IMAX</a>) turns the yaw rate setpoint into a normalized wheel steering command in the range [-1, 1].</li></ol><p>The heading setpoint during the ground roll is the bearing from the takeoff position to the takeoff waypoint, so the nose is kept aligned with the intended runway direction. If no navigation reference is available (takeoff without takeoff waypoint), and during the landing rollout, the controller instead holds the heading that was captured at the moment the wheel steering engaged.</p><p><img src="'+d+'" alt="Wheel steering heading setpoint during the ground roll"></p><p>Operator yaw stick input is added on top of the controller output to &quot;nudge&quot; the vehicle (enabled with <a href="#RWTO_NUDGE">RWTO_NUDGE</a> for takeoff, and <a href="./../advanced_config/parameter_reference#FW_LND_NUDGE">FW_LND_NUDGE</a> for landing).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The gains are scaled with groundspeed (using <a href="./../advanced_config/parameter_reference#FW_AIRSPD_STALL">FW_AIRSPD_STALL</a> as the reference speed) so that the steering becomes less aggressive as the vehicle accelerates. This means the controller should be tuned at low speed, around stall airspeed.</p></div><p>For a smooth takeoff the wheel controller usually needs to be tuned:</p><ol><li>Start with <a href="#FW_WR_P">FW_WR_P</a> and <a href="#FW_WR_FF">FW_WR_FF</a> only (set <a href="#FW_WR_I">FW_WR_I</a> to 0) and taxi/roll the vehicle in <em>Mission mode</em> with active Takeoff waypoint item at low speed.</li><li>Increase the gains until the vehicle tracks the runway heading without noticeable oscillation of the nose.</li><li>Add <a href="#FW_WR_I">FW_WR_I</a> to remove a remaining constant heading offset (e.g. caused by wheel misalignment or crosswind).</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Excessive gains lead to oscillations of the nose during the ground roll, which can quickly become dangerous at higher groundspeed. Always test with increasing speed step by step.</p></div><h3 id="parameters-runway-takeoff" tabindex="-1">Parameters (Runway Takeoff) <a class="header-anchor" href="#parameters-runway-takeoff" aria-label="Permalink to &quot;Parameters (Runway Takeoff)&quot;">​</a></h3><p>Runway takeoff is affected by the following parameters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="RWTO_TKOFF"></a><a href="./../advanced_config/parameter_reference#RWTO_TKOFF">RWTO_TKOFF</a></td><td>Enable runway takeoff</td></tr><tr><td><a id="FW_W_EN"></a><a href="./../advanced_config/parameter_reference#FW_W_EN">FW_W_EN</a></td><td>Enable wheel controller</td></tr><tr><td><a id="RWTO_MAX_THR"></a><a href="./../advanced_config/parameter_reference#RWTO_MAX_THR">RWTO_MAX_THR</a></td><td>Max throttle during runway takeoff</td></tr><tr><td><a id="RWTO_RAMP_TIME"></a><a href="./../advanced_config/parameter_reference#RWTO_RAMP_TIME">RWTO_RAMP_TIME</a></td><td>Throttle ramp up time</td></tr><tr><td><a id="RWTO_ROT_AIRSPD"></a><a href="./../advanced_config/parameter_reference#RWTO_ROT_AIRSPD">RWTO_ROT_AIRSPD</a></td><td>Airspeed threshold to start rotation (pitching up). If not configured by operator is set to 0.9*FW_TKO_AIRSPD.</td></tr><tr><td><a id="RWTO_ROT_TIME"></a><a href="./../advanced_config/parameter_reference#RWTO_ROT_TIME">RWTO_ROT_TIME</a></td><td>This is the time desired to linearly ramp in takeoff pitch constraints during the takeoff rotation.</td></tr><tr><td><a id="FW_TKO_AIRSPD"></a><a href="./../advanced_config/parameter_reference#FW_TKO_AIRSPD">FW_TKO_AIRSPD</a></td><td>Airspeed setpoint during the takeoff climbout phase (after rotation). If not configured by operator is set to FW_AIRSPD_MIN.</td></tr><tr><td><a id="RWTO_NUDGE"></a><a href="./../advanced_config/parameter_reference#RWTO_NUDGE">RWTO_NUDGE</a></td><td>Enable wheel controller nudging while on the runway</td></tr><tr><td><a id="FW_WING_SPAN"></a><a href="./../advanced_config/parameter_reference#FW_WING_SPAN">FW_WING_SPAN</a></td><td>The wingspan of the vehicle. Used to prevent wingstrikes.</td></tr><tr><td><a id="FW_WING_HEIGHT"></a><a href="./../advanced_config/parameter_reference#FW_WING_HEIGHT">FW_WING_HEIGHT</a></td><td>The height of the wings above ground (ground clearance). Used to prevent wingstrikes.</td></tr></tbody></table><h3 id="parameters-wheel-controller" tabindex="-1">Parameters (Wheel Controller) <a class="header-anchor" href="#parameters-wheel-controller" aria-label="Permalink to &quot;Parameters (Wheel Controller)&quot;">​</a></h3><p>The <a href="#wheel_controller">wheel controller</a> is affected by the following parameters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a href="#FW_W_EN">FW_W_EN</a></td><td>Enable wheel controller</td></tr><tr><td><a id="FW_W_RMAX"></a><a href="./../advanced_config/parameter_reference#FW_W_RMAX">FW_W_RMAX</a></td><td>Maximum yaw rate setpoint the heading controller outputs</td></tr><tr><td><a id="FW_WR_P"></a><a href="./../advanced_config/parameter_reference#FW_WR_P">FW_WR_P</a></td><td>Yaw rate controller proportional gain</td></tr><tr><td><a id="FW_WR_I"></a><a href="./../advanced_config/parameter_reference#FW_WR_I">FW_WR_I</a></td><td>Yaw rate controller integrator gain (trims a constant heading error)</td></tr><tr><td><a id="FW_WR_IMAX"></a><a href="./../advanced_config/parameter_reference#FW_WR_IMAX">FW_WR_IMAX</a></td><td>Yaw rate controller integrator limit</td></tr><tr><td><a id="FW_WR_FF"></a><a href="./../advanced_config/parameter_reference#FW_WR_FF">FW_WR_FF</a></td><td>Yaw rate controller feed forward gain</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../flight_modes_mc/takeoff">Takeoff Mode (MC)</a></li><li><a href="./../flight_modes_fw/mission#mission-takeoff">Planning a mission takeoff</a></li></ul>',39))])}const v=l(c,[["render",u]]);export{b as __pageData,v as default};
